import type { AlignmentAction, AlignmentPosition } from "./alignment-control-state";

/** A layer's box, in your canvas's units. */
export type AlignmentRect = { id: string; x: number; y: number; width: number; height: number };
export type AlignmentBounds = Omit<AlignmentRect, "id">;

/** The box around every rect. */
export function boundsOf(rects: AlignmentBounds[]): AlignmentBounds {
  const left = Math.min(...rects.map((rect) => rect.x));
  const top = Math.min(...rects.map((rect) => rect.y));
  const right = Math.max(...rects.map((rect) => rect.x + rect.width));
  const bottom = Math.max(...rects.map((rect) => rect.y + rect.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
}

const place = (start: number, size: number, span: number, at: AlignmentPosition["x"]) =>
  at === "start" ? start : at === "end" ? start + span - size : start + (span - size) / 2;

/**
 * Applies an action to the selected rects, in their original order. One rect aligns to `parent`,
 * several to their own bounds. Distributing keeps the outer two in place and evens the gaps between all of them.
 */
export function alignRects<T extends AlignmentRect>(rects: T[], action: AlignmentAction, parent?: AlignmentBounds): T[] {
  if (rects.length === 0) return rects;
  if (action === "distribute-horizontal" || action === "distribute-vertical") {
    if (rects.length < 3) return rects;
    const horizontal = action === "distribute-horizontal";
    const start = (rect: AlignmentRect) => (horizontal ? rect.x : rect.y);
    const size = (rect: AlignmentRect) => (horizontal ? rect.width : rect.height);
    const sorted = [...rects].sort((a, b) => start(a) - start(b));
    const first = start(sorted[0]);
    const last = Math.max(...sorted.map((rect) => start(rect) + size(rect)));
    const gap = (last - first - sorted.reduce((sum, rect) => sum + size(rect), 0)) / (sorted.length - 1);
    const moved = new Map<string, number>();
    let cursor = first;
    for (const rect of sorted) {
      moved.set(rect.id, cursor);
      cursor += size(rect) + gap;
    }
    return rects.map((rect) => ({ ...rect, [horizontal ? "x" : "y"]: moved.get(rect.id)! }));
  }
  const bounds = rects.length === 1 && parent ? parent : boundsOf(rects);
  return rects.map((rect) => {
    switch (action) {
      case "left":
        return { ...rect, x: bounds.x };
      case "center":
        return { ...rect, x: place(bounds.x, rect.width, bounds.width, "center") };
      case "right":
        return { ...rect, x: place(bounds.x, rect.width, bounds.width, "end") };
      case "top":
        return { ...rect, y: bounds.y };
      case "middle":
        return { ...rect, y: place(bounds.y, rect.height, bounds.height, "center") };
      default:
        return { ...rect, y: place(bounds.y, rect.height, bounds.height, "end") };
    }
  });
}

/** Moves a rect to a grid position inside its parent. */
export function positionRect<T extends AlignmentBounds>(rect: T, position: AlignmentPosition, parent: AlignmentBounds): T {
  return { ...rect, x: place(parent.x, rect.width, parent.width, position.x), y: place(parent.y, rect.height, parent.height, position.y) };
}

/** Where a rect sits in its parent, or null when it is not at one of the nine positions. */
export function positionOf(rect: AlignmentBounds, parent: AlignmentBounds, tolerance = 0.5): AlignmentPosition | null {
  const axis = (start: number, size: number, from: number, span: number) =>
    (["start", "center", "end"] as const).find((at) => Math.abs(place(from, size, span, at) - start) <= tolerance) ?? null;
  const x = axis(rect.x, rect.width, parent.x, parent.width);
  const y = axis(rect.y, rect.height, parent.y, parent.height);
  return x && y ? { x, y } : null;
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactElement, type RefObject, forwardRef, useRef } from "react";
import { type AlignmentControlMessages, type AlignmentPosition, defaultMessages } from "./alignment-control-state";
import { cn } from "@/lib/utils";

const axis = ["start", "center", "end"] as const;
const cells = axis.flatMap((y) => axis.map((x) => ({ x, y })));
const same = (a: AlignmentPosition | null, b: AlignmentPosition) => !!a && a.x === b.x && a.y === b.y;

export type AlignmentGridProps = Omit<ComponentPropsWithoutRef<"div">, "defaultValue" | "onChange"> & {
  /** Where the layer sits in its frame; null when it is between positions or a selection differs. */
  value: AlignmentPosition | null;
  /** Called with the position picked. Your app moves the layer. */
  onValueChange: (position: AlignmentPosition) => void;
  disabled?: boolean;
  /** Name each cell in a tooltip on hover, such as "Top left". On by default. */
  tooltips?: boolean;
  /** Tooltip entrance transitions. Reduced motion is always honored. */
  motion?: boolean;
  tooltipClassName?: string;
  /** Class for each cell and for the mark inside it. */
  cellClassName?: string;
  markClassName?: string;
  messages?: Partial<Pick<AlignmentControlMessages, "grid" | "position">>;
};

/**
 * Nine positions for a layer in its frame, as one radio group: arrow keys move across and down,
 * and the current position holds the tab stop.
 */
export const AlignmentGrid = forwardRef<HTMLDivElement, AlignmentGridProps>(function AlignmentGrid(
  { value, onValueChange, disabled = false, tooltips = true, motion = true, tooltipClassName, cellClassName, markClassName, messages: messagesProp, className, onKeyDown, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const root = useRef<HTMLDivElement | null>(null);
  // With no position, the centre takes the tab stop.
  const focusable = value ?? { x: "center", y: "center" };
  return (
    <div
      ref={(node) => {
        root.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      role="radiogroup"
      aria-label={messages.grid}
      aria-disabled={disabled || undefined}
      data-disabled={disabled || undefined}
      data-mixed={value === null || undefined}
      className={cn(
        "grid size-[calc(var(--uicoolkit-field-height,2.5rem)*2-0.5rem)] shrink-0 grid-cols-3 grid-rows-3 rounded-md border border-input bg-muted p-0.5 dark:bg-input/40 data-disabled:opacity-50",
        className,
      )}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || disabled) return;
        const from = (event.target as HTMLElement).dataset;
        if (!from.x || !from.y) return;
        const step = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[event.key];
        if (!step) return;
        event.preventDefault();
        const x = axis[Math.min(2, Math.max(0, axis.indexOf(from.x as AlignmentPosition["x"]) + step[0]))];
        const y = axis[Math.min(2, Math.max(0, axis.indexOf(from.y as AlignmentPosition["y"]) + step[1]))];
        onValueChange({ x, y });
        event.currentTarget.querySelector<HTMLElement>(`[data-x="${x}"][data-y="${y}"]`)?.focus();
      }}
      {...props}
    >
      <Tooltip.Provider delay={400}>
        {cells.map((cell) => {
          const button = (
            <button
              key={`${cell.y}-${cell.x}`}
              type="button"
              role="radio"
              data-x={cell.x}
              data-y={cell.y}
              aria-checked={same(value, cell)}
              aria-label={messages.position(cell)}
              disabled={disabled}
              tabIndex={same(focusable, cell) ? 0 : -1}
              onClick={() => onValueChange(cell)}
              className={cn(
                "group/cell grid place-items-center rounded-sm outline-none focus-visible:bg-foreground/10 disabled:cursor-not-allowed",
                cellClassName,
              )}
            >
              {/* A dot for each spot; the current one becomes the layer, and hovering previews it. */}
              <span
                aria-hidden
                className={cn(
                  "size-1 rounded-full bg-muted-foreground/50 transition-all duration-150 motion-reduce:transition-none",
                  "group-enabled/cell:group-hover/cell:size-2 group-enabled/cell:group-hover/cell:rounded-[2px] group-enabled/cell:group-hover/cell:bg-muted-foreground",
                  "group-aria-checked/cell:size-2.5 group-aria-checked/cell:rounded-[3px] group-aria-checked/cell:bg-foreground",
                  markClassName,
                )}
              />
            </button>
          );
          // A cell's name on hover, as with the toolbar's buttons; disabled cells skip it.
          return tooltips && !disabled ? (
            <CellTip key={`${cell.y}-${cell.x}`} label={messages.position(cell)} container={root} motion={motion} className={tooltipClassName}>
              {button}
            </CellTip>
          ) : (
            button
          );
        })}
      </Tooltip.Provider>
    </div>
  );
});

type CellTipProps = { label: string; container: RefObject<HTMLDivElement | null>; motion: boolean; className?: string; children: ReactElement };

/** A cell's name on hover, portalled into the grid so it keeps the grid's theme. */
function CellTip({ label, container, motion, className, children }: CellTipProps) {
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={children} />
      <Tooltip.Portal container={container}>
        <Tooltip.Positioner side="top" sideOffset={6} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              motion &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
              className,
            )}
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

"use client";

import { type ComponentPropsWithoutRef, type MutableRefObject, type Ref, createContext, useContext } from "react";

/** The six align actions and the two distribute actions. */
export type AlignmentAction = "left" | "center" | "right" | "top" | "middle" | "bottom" | "distribute-horizontal" | "distribute-vertical";

/** What an align action lines layers up against: the parent frame for one layer, the selection's bounds for several. */
export type AlignmentTarget = "parent" | "selection";

/** A spot in a 3×3 grid: where a layer sits in its frame on each axis. */
export type AlignmentPosition = { x: "start" | "center" | "end"; y: "start" | "center" | "end" };

/** Replaceable text, for example to translate. */
export type AlignmentControlMessages = {
  toolbar: string;
  actions: Record<AlignmentAction, string>;
  /** Shown in the tooltip of an action that needs more layers selected. */
  needs: (count: number) => string;
  grid: string;
  position: (position: AlignmentPosition) => string;
};

const words = { start: { x: "left", y: "Top" }, center: { x: "centre", y: "Middle" }, end: { x: "right", y: "Bottom" } } as const;

export const defaultMessages: AlignmentControlMessages = {
  toolbar: "Alignment",
  actions: {
    left: "Align left",
    center: "Align horizontal centres",
    right: "Align right",
    top: "Align top",
    middle: "Align vertical centres",
    bottom: "Align bottom",
    "distribute-horizontal": "Distribute horizontal spacing",
    "distribute-vertical": "Distribute vertical spacing",
  },
  needs: (count) => (count === 1 ? "Select a layer" : `Select ${count} or more layers`),
  grid: "Position in frame",
  position: ({ x, y }) => (x === "center" && y === "center" ? "Centre" : `${words[y].y} ${words[x].x}`),
};

/** How many layers each action needs. */
export const minimumFor = (action: AlignmentAction) => (action.startsWith("distribute") ? 3 : 1);

export type AlignmentControlProps = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** How many layers are selected. One aligns to its parent; distribute needs three or more. */
  selectionCount: number;
  /** Called with the action and what it aligns to. Your app moves the layers. */
  onAlign: (action: AlignmentAction, detail: { target: AlignmentTarget }) => void;
  /** Shortcut text shown in each action's tooltip, such as "Alt+A". Your app binds the keys. */
  shortcuts?: Partial<Record<AlignmentAction, string>>;
  disabled?: boolean;
  /** Tooltip transitions. Reduced motion is always honored. */
  motion?: boolean;
  messages?: Partial<AlignmentControlMessages>;
};

export type AlignmentControlContextValue = {
  selectionCount: number;
  align: (action: AlignmentAction) => void;
  shortcuts: Partial<Record<AlignmentAction, string>>;
  disabled: boolean;
  animated: boolean;
  messages: AlignmentControlMessages;
  /** The action that holds the toolbar's single tab stop. */
  active: AlignmentAction | null;
  setActive: (action: AlignmentAction) => void;
  rootRef: MutableRefObject<HTMLDivElement | null>;
};

export const AlignmentControlContext = createContext<AlignmentControlContextValue | null>(null);

export function useAlignmentControl() {
  const context = useContext(AlignmentControlContext);
  if (!context) throw new Error("Alignment Control parts must be used inside <AlignmentControl>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactNode, forwardRef, useEffect, useRef, useState } from "react";
import {
  type AlignmentAction,
  type AlignmentControlContextValue,
  type AlignmentControlProps,
  AlignmentControlContext,
  defaultMessages,
  mergeRefs,
  minimumFor,
  useAlignmentControl,
} from "./alignment-control-state";
import { cn } from "@/lib/utils";

const actionSelector = "[data-align-action]";

/**
 * Align and distribute buttons for the selected layers, as one toolbar: arrow keys move between
 * the buttons and Tab leaves it. The control reports the action; your app moves the layers.
 */
export const AlignmentControl = forwardRef<HTMLDivElement, AlignmentControlProps>(function AlignmentControl(
  { selectionCount, onAlign, shortcuts = {}, disabled = false, motion = true, messages: messagesProp, className, onKeyDown, children, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp, actions: { ...defaultMessages.actions, ...messagesProp?.actions } };
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [active, setActive] = useState<AlignmentAction | null>(null);

  // Give the tab stop to the first button until one is focused, and again if that button goes away.
  useEffect(() => {
    const buttons = [...(rootRef.current?.querySelectorAll<HTMLElement>(actionSelector) ?? [])];
    if (buttons.some((button) => button.dataset.alignAction === active)) return;
    const first = buttons[0]?.dataset.alignAction as AlignmentAction | undefined;
    if (first) setActive(first);
  }, [active, children]);

  const context: AlignmentControlContextValue = {
    selectionCount,
    align: (action) => {
      if (disabled || selectionCount < minimumFor(action)) return;
      onAlign(action, { target: selectionCount === 1 ? "parent" : "selection" });
    },
    shortcuts,
    disabled,
    animated: motion,
    messages,
    active,
    setActive,
    rootRef,
  };

  return (
    <AlignmentControlContext.Provider value={context}>
      <Tooltip.Provider delay={400}>
        <div
          ref={mergeRefs(ref, rootRef)}
          role="toolbar"
          aria-label={messages.toolbar}
          aria-disabled={disabled || undefined}
          data-disabled={disabled || undefined}
          className={cn("flex flex-wrap items-center gap-1.5", className)}
          onKeyDown={(event) => {
            onKeyDown?.(event);
            if (event.defaultPrevented) return;
            const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>(actionSelector)].filter((button) => !button.hasAttribute("disabled"));
            const index = buttons.indexOf(document.activeElement as HTMLElement);
            if (index < 0) return;
            const next =
              event.key === "ArrowRight" || event.key === "ArrowDown"
                ? buttons[(index + 1) % buttons.length]
                : event.key === "ArrowLeft" || event.key === "ArrowUp"
                  ? buttons[(index - 1 + buttons.length) % buttons.length]
                  : event.key === "Home"
                    ? buttons[0]
                    : event.key === "End"
                      ? buttons[buttons.length - 1]
                      : null;
            if (!next) return;
            event.preventDefault();
            next.focus();
          }}
          {...props}
        >
          {children}
        </div>
      </Tooltip.Provider>
    </AlignmentControlContext.Provider>
  );
});

/** A boxed set of buttons, such as the horizontal aligns. */
export const AlignmentControlGroup = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function AlignmentControlGroup({ className, ...props }, ref) {
  return (
    <div
      ref={ref}
      role="group"
      className={cn("flex h-8 items-center gap-0.5 rounded-md border border-input bg-muted p-0.5 dark:bg-input/40", className)}
      {...props}
    />
  );
});

// Each icon is a guide line with two layers against it, drawn on a 16-unit grid.
const bar = (x: number, y: number, width: number, height: number) => <rect x={x} y={y} width={width} height={height} rx={1} fill="currentColor" />;
const line = (x1: number, y1: number, x2: number, y2: number) => <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" />;
const glyphs: Record<AlignmentAction, ReactNode> = {
  left: [line(2, 2, 2, 14), bar(4.5, 4, 8, 3), bar(4.5, 9, 5, 3)],
  center: [line(8, 2, 8, 14), bar(3, 4, 10, 3), bar(5, 9, 6, 3)],
  right: [line(14, 2, 14, 14), bar(3.5, 4, 8, 3), bar(6.5, 9, 5, 3)],
  top: [line(2, 2, 14, 2), bar(4, 4.5, 3, 8), bar(9, 4.5, 3, 5)],
  middle: [line(2, 8, 14, 8), bar(4, 3, 3, 10), bar(9, 5, 3, 6)],
  bottom: [line(2, 14, 14, 14), bar(4, 3.5, 3, 8), bar(9, 6.5, 3, 5)],
  "distribute-horizontal": [line(2, 2, 2, 14), line(14, 2, 14, 14), bar(6.5, 4, 3, 8)],
  "distribute-vertical": [line(2, 2, 14, 2), line(2, 14, 14, 14), bar(4, 6.5, 8, 3)],
};

/** The icon for an action, for menus or custom buttons. */
export function AlignmentIcon({ action, className }: { action: AlignmentAction; className?: string }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden className={cn("size-4 shrink-0", className)}>
      {Array.isArray(glyphs[action]) ? (glyphs[action] as ReactNode[]).map((part, index) => <g key={index}>{part}</g>) : glyphs[action]}
    </svg>
  );
}

type ButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  action: AlignmentAction;
  /** Class for the tooltip. */
  tooltipClassName?: string;
};

/**
 * One action. It stays focusable when the selection is too small for it, and its tooltip says what it needs.
 */
export const AlignmentControlButton = forwardRef<HTMLButtonElement, ButtonProps>(function AlignmentControlButton(
  { action, tooltipClassName, className, onClick, onFocus, ...props },
  ref,
) {
  const control = useAlignmentControl();
  const minimum = minimumFor(action);
  const unavailable = control.selectionCount < minimum;
  const label = control.messages.actions[action];
  const shortcut = control.shortcuts[action];
  const button = (
    <button
      ref={ref}
      type="button"
      data-align-action={action}
      aria-label={label}
      aria-keyshortcuts={shortcut}
      aria-disabled={unavailable || undefined}
      disabled={control.disabled}
      tabIndex={control.active === action ? 0 : -1}
      onFocus={(event) => {
        onFocus?.(event);
        control.setActive(action);
      }}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) control.align(action);
      }}
      className={cn(
        "grid size-7 shrink-0 place-items-center rounded-sm text-muted-foreground outline-none transition-[color,background-color,box-shadow,transform] select-none",
        "hover:bg-background hover:text-foreground hover:shadow-xs active:scale-95 focus-visible:bg-foreground/10 focus-visible:text-foreground",
        "aria-disabled:opacity-40 aria-disabled:hover:bg-transparent aria-disabled:hover:text-muted-foreground aria-disabled:hover:shadow-none aria-disabled:active:scale-100",
        "disabled:pointer-events-none disabled:opacity-40",
        className,
      )}
      {...props}
    >
      <AlignmentIcon action={action} />
    </button>
  );
  if (control.disabled) return button;
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={button} />
      <Tooltip.Portal container={control.rootRef}>
        <Tooltip.Positioner side="top" sideOffset={6} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "flex items-center gap-2 rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              control.animated &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
              tooltipClassName,
            )}
          >
            <span>{unavailable ? `${label} · ${control.messages.needs(minimum)}` : label}</span>
            {shortcut && !unavailable && <kbd className="font-sans text-background/60">{shortcut}</kbd>}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
});

"use client";

export {
  type AlignmentAction,
  type AlignmentTarget,
  type AlignmentPosition,
  type AlignmentControlProps,
  type AlignmentControlMessages,
  useAlignmentControl,
} from "./alignment-control-state";
export { AlignmentControl, AlignmentControlGroup, AlignmentControlButton, AlignmentIcon } from "./alignment-control-toolbar";
export { AlignmentGrid, type AlignmentGridProps } from "./alignment-control-grid";
export { type AlignmentRect, type AlignmentBounds, alignRects, boundsOf, positionRect, positionOf } from "./alignment-control-geometry";
